"""Apply the prospective per-canonical-bank mask rule to all four raw diagnostic queries."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def discover(path):
    analysis = json.loads(path.read_text())
    assert analysis['valid'] and len(analysis['owners']) == 4
    by_query = []
    for owner in analysis['owners']:
        assert owner['valid']
        raw_path = Path(owner['path'])
        assert sha(raw_path) == owner['sha256']
        records = [json.loads(line) for line in raw_path.read_text().splitlines()]
        targets = [record for record in records if record['type'] == 'target']
        banks = {}
        for target in targets:
            canonical = target['canonical']
            key = targets[canonical]['name']
            bank = banks.setdefault(key, {'canonicalIndex': canonical, 'aliasNames': [],
                'ordinaryHit': 0, 'factorHit': 0, 'factorWeakMiss': 0, 'factorWitnessMiss': 0,
                'publicationCall': 0, 'publicationComplete': 0, 'publicationWrite': 0,
                'pageAdmitted': 0, 'pageBytesGranted': 0, 'pageRefused': 0})
            bank['aliasNames'].append(target['name'])
            for field in bank:
                if field not in ('canonicalIndex', 'aliasNames'):
                    bank[field] += target[field]
        by_query.append({'owner': owner['header']['owner'], 'stage': owner['query']['stage'],
            'iteration': owner['query']['iteration'], 'banks': banks,
            'lazyValueCalls': owner['query']['counters']['lazyValueCalls'],
            'ledgerPeakBytes': owner['query']['ledgerPeakBytes']})
    names = set(by_query[0]['banks'])
    assert all(set(query['banks']) == names for query in by_query)
    decisions = {}
    for name in sorted(names):
        banks = [query['banks'][name] for query in by_query]
        checks = {
            'positiveAdmissionsEveryQuery': all(bank['pageAdmitted'] > 0 for bank in banks),
            'positiveCompletedPublicationsEveryQuery': all(bank['publicationComplete'] > 0 for bank in banks),
            'zeroSuccessfulFactorHitsEveryQuery': all(bank['factorHit'] == 0 for bank in banks),
            'zeroFactorWeakMissesEveryQuery': all(bank['factorWeakMiss'] == 0 for bank in banks),
            'zeroFactorWitnessMissesEveryQuery': all(bank['factorWitnessMiss'] == 0 for bank in banks),
        }
        decisions[name] = {'candidate': all(checks.values()), 'checks': checks,
            'canonicalIndex': banks[0]['canonicalIndex'], 'aliasNames': banks[0]['aliasNames']}
    return {'input': str(path), 'inputSha256': sha(path), 'queries': by_query, 'decisions': decisions,
        'candidateCanonicalNames': [name for name, decision in decisions.items() if decision['candidate']],
        'proofLimit': 'Observed full-consumption executions only. Zero hits/misses do not prove no future useful replay.'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--suite', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    summary = json.loads((args.suite / 'analysis.json').read_text())
    assert summary['valid']
    fixtures = {name: discover(Path(data['analysis'])) for name, data in summary['fixtures'].items()}
    result = {'format': 1, 'rule': 'positive admitted pages and completed publications; zero successful factor hits, '
        'weak misses and witness misses in all four queries, aggregating requested counters by canonical alias bank',
        'scriptSha256': sha(Path(__file__)), 'fixtures': fixtures, 'performanceInference': False}
    with args.output.open('x') as out:
        json.dump(result, out, indent=2, sort_keys=True)
        out.write('\n')
    print(json.dumps({name: value['candidateCanonicalNames'] for name, value in fixtures.items()}))


if __name__ == '__main__':
    main()
